<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialPublicKeyAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialPublicKeyAccessor trait.
 *
 * Covers null default, string/VO assignment via withPublicKey,
 * getPublicKey/publicKey accessors, and isPublicKeyChanged with/without original.
 */
class UserWebauthnCredentialPublicKeyAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPublicKey creates a new instance with the PublicKey set
     * from a string value, and getPublicKey returns the primitive string.
     */
    public function testWithPublicKeyFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialPublicKeyAccessorUnitTest();

        // Act
        $result = $holder->withPublicKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPublicKey());
    }
    /**
     * Asserts that withpublicKey has access to the value object
     * from a string value, and getPublicKey returns the primitive string.
     */
    public function testWithPublicKeyFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialPublicKeyAccessorUnitTest();

        // Act
        $result = $holder->withPublicKey('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->publicKey()->value());
    }
    public function testChangedPublicKey(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialPublicKeyAccessorUnitTest()->withPublicKey('one');
        $original = $holder->withPublicKey('one');
        $same = $holder->withPublicKey('one');
        $modified = $holder->withPublicKey('other');

        // Act
        $withSame = $original->isPublicKeyChanged($same);
        $withDiferent = $original->isPublicKeyChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialPublicKeyAccessorUnitTest
{
    use UserWebauthnCredentialPublicKeyAccessor;
}
